package ociresources

import (
	"cmp"
	"slices"
	"strings"
)

// The ranks of matchTier, lowest first.
const (
	tierExact      = iota // the name is the query
	tierLastEquals        // the last path segment is the query
	tierLastPrefix        // the last path segment starts with the query
	tierContains          // the name contains the query
	tierNoMatch           // nothing in the name matches
)

// matchTier ranks name against query, lowest first, case-insensitive.
func matchTier(query, name string) int {
	q, n := strings.ToLower(query), strings.ToLower(name)
	last := n[strings.LastIndex(n, "/")+1:]
	switch {
	case n == q:
		return tierExact
	case last == q:
		return tierLastEquals
	case strings.HasPrefix(last, q):
		return tierLastPrefix
	case strings.Contains(n, q):
		return tierContains
	}
	return tierNoMatch
}

// sortSearchRows orders rows by matchTier, then lower-cased name, then
// registry alias (label), then EntryKey. The result depends only on the rows
// and the query, never on which registry answered first (DEVDESK-302). Stars
// play no part.
func sortSearchRows(query string, rows []searchRow) {
	slices.SortStableFunc(rows, func(a, b searchRow) int {
		return cmp.Or(
			cmp.Compare(matchTier(query, a.img.Name), matchTier(query, b.img.Name)),
			cmp.Compare(strings.ToLower(a.img.Name), strings.ToLower(b.img.Name)),
			cmp.Compare(a.label, b.label),
			cmp.Compare(a.img.EntryKey, b.img.EntryKey),
		)
	})
}
			func(searchRow) string { return theme.IconDocker },
			func(searchRow) lipgloss.Style { return theme.IconStyle(theme.IconRoleImage) },
		),
		{
			Title: "Name", Sizing: datatable.SizingContent, MinWidth: 24, Flex: 1,
			Cell:   func(r searchRow) string { return r.img.Name },
			Search: func(r searchRow) string { return r.img.Name },
		},
		{
			Title: "Registry", Sizing: datatable.SizingContent, MinWidth: 16,
			Cell: func(r searchRow) string { return r.label },
		},
	}
}

// newSearchTable builds the level 1 table; rebuildSearchTable orders its rows.
func newSearchTable() *datatable.Model[searchRow] {
	t := datatable.New(datatable.Config[searchRow]{
		Columns:    searchColumns(),
		SortColumn: -1,
	})
	return &t
}

// rebuildSearchTable hands the collected images to the table.
func (b *RegistryBrowser) rebuildSearchTable() {
	rows := make([]searchRow, len(b.images))
	for i, img := range b.images {
		label := ""
		if e := b.entryFor(img.EntryKey); e != nil {
			label = entryAlias(*e)
			if label == "" {
				label = e.URL
			}
		}
		rows[i] = searchRow{img: img, label: label}
	}
	sortSearchRows(b.searchQuery, rows)
	b.searchTable.SetItems(rows)
	b.resizeTables()
}

// AddImageResults takes one registry's answer. It returns false, touching
// nothing, when the answer belongs to another lot. pendingSearches never goes
// below zero.
func (b *RegistryBrowser) AddImageResults(msg ImageSearchResultMsg) bool {
	if msg.Gen != b.gen {
		return false
	}
	if b.pendingSearches > 0 {
		b.pendingSearches--
	}
	if msg.Err == nil {
		for _, img := range msg.Images {
			img.EntryKey = msg.EntryKey
			b.images = append(b.images, img)
		}
	}
	b.rebuildSearchTable()
	return true
}

// handleImagesKeyMsg handles the keys of the level 1 table. esc acts in
// order: the filter bar while it is open, then a confirmed query, then it
// cancels the lot and goes back to the form (which keeps the typed name and
// the selection). The lot's late answers are no longer wanted and are dropped
// (TestEscAtLevelOneCancelsTheLotAndIgnoresItsLateAnswers). enter does
// nothing: a row has no action yet.
func (b *RegistryBrowser) handleImagesKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
	if b.searchTable.InEditMode() {
		return b, b.searchTable.Update(msg)
	}
	switch msg.String() {
	case "esc":
		if bar := b.searchTable.FilterBar(); bar.SearchQuery() != "" {
			bar.ClearSearch()
			b.searchTable.SetItems(b.searchTable.Items())
			return b, nil
		}
		b.cancelInFlight()
		b.gen = nextBrowserGen()
		b.pendingSearches = 0
		b.state = browserStateInput
		b.searchTable.Blur()
		b.updateFocus()
		return b, nil
	case "enter":
		return b, nil
	}
	return b, b.searchTable.Update(msg)
}

// handleImageSearchResult records one registry's answer; a stale one is ignored.
func (m Model) handleImageSearchResult(msg ImageSearchResultMsg) (tea.Model, tea.Cmd) {
	if m.registryBrowser == nil || !m.registryBrowser.AddImageResults(msg) {
		return m, nil
	}
	if msg.Err != nil {
		alias := msg.EntryKey
		if e := m.registryBrowser.entryFor(msg.EntryKey); e != nil {
			alias = entryAlias(*e)
		}
		log.Printf("ERROR [oci_resources] image search on %s: %s", alias, jobs.SafeCause(msg.Err))
	}
	return m, nil
}

// handleRegistryBrowserWarn shows the browser's warning in the footer.
func (m Model) handleRegistryBrowserWarn(msg RegistryBrowserWarnMsg) (tea.Model, tea.Cmd) {
	return m, m.footer.Warn(strings.TrimSpace(msg.Text))
}

// imageSearchDeadline bounds one registry's whole search.
var imageSearchDeadline = 15 * time.Second

// targetFor describes entry for the Searcher, with the same alias, address and
// credentials (D12) the tag flow uses.
func (b *RegistryBrowser) targetFor(entry browserRegistryEntry) imagesearch.Target {
	user, pass := b.credsFor(entry)
	return imagesearch.Target{
		EntryKey: entry.key, Alias: entryAlias(entry), RegistryURL: entry.URL,
		APIURL: registryAPIURL(entry.URL), RepoPrefix: entry.repoPrefix,
		Username: user, Password: pass,
	}
}

// startImageSearch opens a lot and asks the Searcher once per entry.
func (b *RegistryBrowser) startImageSearch(query string, entries []browserRegistryEntry) (*RegistryBrowser, tea.Cmd) {
	ctx := b.beginRequests()
	b.images = nil
	b.searchQuery = query
	b.searchTable.SetItems(nil)

	cmds := make([]tea.Cmd, 0, len(entries))
	for _, entry := range entries {
		b.pendingSearches++
		cmds = append(cmds, searchImagesCmd(ctx, b.gen, b.targetFor(entry), imagesearch.Query{Text: query}, b.searcher, imageSearchDeadline))
	}
	b.state = browserStateImages
	b.searchTable.Focus()
	return b, tea.Batch(cmds...)
}

// searchImagesCmd runs one registry's search under deadline (read from
// imageSearchDeadline by the caller, in Update), inside the lot's context. It
// reads no model state (Rule 110).
func searchImagesCmd(parent context.Context, gen uint64, t imagesearch.Target, q imagesearch.Query, s imagesearch.Searcher, deadline time.Duration) tea.Cmd {
	return func() tea.Msg {
		ctx, cancel := context.WithTimeout(parent, deadline)
		defer cancel()
		images, partial, err := s.Search(ctx, t, q)
		return ImageSearchResultMsg{Gen: gen, EntryKey: t.EntryKey, Images: images, Partial: partial, Err: err}
	}
}
